import{_ as a,c as o,o as t,ag as r}from"./chunks/framework.DPDPlp3K.js";const c=JSON.parse('{"title":"Shopify","description":"","frontmatter":{},"headers":[],"relativePath":"shopify/shopify.md","filePath":"shopify/shopify.md"}'),i={name:"shopify/shopify.md"};function s(h,e,p,l,n,d){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="shopify" tabindex="-1">Shopify <a class="header-anchor" href="#shopify" aria-label="Permalink to &quot;Shopify&quot;">​</a></h1><h2 id="响应式布局" tabindex="-1">响应式布局 <a class="header-anchor" href="#响应式布局" aria-label="Permalink to &quot;响应式布局&quot;">​</a></h2><p><a href="https://chromewebstore.google.com/detail/responsive-viewer/inmopeiepgfljkpkidclfgbgbmfcennb" target="_blank" rel="noreferrer">https://chromewebstore.google.com/detail/responsive-viewer/inmopeiepgfljkpkidclfgbgbmfcennb</a></p><h2 id="ga4" tabindex="-1">GA4 <a class="header-anchor" href="#ga4" aria-label="Permalink to &quot;GA4&quot;">​</a></h2><p><a href="https://chromewebstore.google.com/detail/adswerve-datalayer-inspec/kmcbdogdandhihllalknlcjfpdjcleom" target="_blank" rel="noreferrer">https://chromewebstore.google.com/detail/adswerve-datalayer-inspec/kmcbdogdandhihllalknlcjfpdjcleom</a></p><h2 id="shopify-web-pixel" tabindex="-1">Shopify Web Pixel <a class="header-anchor" href="#shopify-web-pixel" aria-label="Permalink to &quot;Shopify Web Pixel&quot;">​</a></h2><p><a href="https://shopify.dev/docs/apps/build/marketing/pixels" target="_blank" rel="noreferrer">https://shopify.dev/docs/apps/build/marketing/pixels</a></p><p>分为 Custom Pixel and App Pixel</p><h2 id="seo" tabindex="-1">SEO <a class="header-anchor" href="#seo" aria-label="Permalink to &quot;SEO&quot;">​</a></h2><p><a href="https://chromewebstore.google.com/detail/detailed-seo-extension/pfjdepjjfjjahkjfpkcgfmfhmnakjfba" target="_blank" rel="noreferrer">https://chromewebstore.google.com/detail/detailed-seo-extension/pfjdepjjfjjahkjfpkcgfmfhmnakjfba</a></p><h2 id="什么是电商漏斗" tabindex="-1">什么是电商漏斗 <a class="header-anchor" href="#什么是电商漏斗" aria-label="Permalink to &quot;什么是电商漏斗&quot;">​</a></h2><p>在 Shopify 语境里，漏斗（funnel） 指的是用户从进店到下单的转化路径，以及每一步有多少人留下来、多少人流失。</p><p>常见电商漏斗大致是：</p><ol><li>Session / 进站 — 有人打开店铺</li><li>Product / 看商品 — 进入 PDP</li><li>Add to cart / 加购</li><li>Checkout / 进结账</li><li>Purchase / 完成支付</li></ol><p>每一层人数通常会变少，画出来像漏斗，所以叫漏斗。看的是哪一步掉得最多（比如加购多、结账少），用来定位问题。</p><p>Shopify 后台里也会用这个概念，例如 Analytics 里的转化相关报表，以及 ShopifyQL 里的 search / recommendation conversion funnel（搜索漏斗、推荐漏斗等）。</p><h2 id="对接splitit-payment分期支付" tabindex="-1">对接Splitit payment分期支付 <a class="header-anchor" href="#对接splitit-payment分期支付" aria-label="Permalink to &quot;对接Splitit payment分期支付&quot;">​</a></h2><p><a href="https://developers.splitit.com/mcp-servers/docs" target="_blank" rel="noreferrer">https://developers.splitit.com/mcp-servers/docs</a></p><h2 id="shopify-webhook-测试" tabindex="-1">shopify webhook 测试 <a class="header-anchor" href="#shopify-webhook-测试" aria-label="Permalink to &quot;shopify webhook 测试&quot;">​</a></h2><p>公共webhook <a href="https://smee.io/" target="_blank" rel="noreferrer">https://smee.io/</a> -&gt; Start a new channel -&gt; 保持页面打开</p><p>Admin -&gt; Settings → Notifications → Webhooks → Create webhook Event：Order creation Format：JSON URL：上面的 smee channel 地址</p><p>下一笔测试单完成后，smee 页面就会出现完整 payload</p><p>Draft order 的 customAttributes 付款后会出现在订单 webhook 的 note_attributes 里</p><h2 id="直播" tabindex="-1">直播 <a class="header-anchor" href="#直播" aria-label="Permalink to &quot;直播&quot;">​</a></h2><p><a href="https://apps.shopify.com/firework" target="_blank" rel="noreferrer">https://apps.shopify.com/firework</a><a href="https://docs.firework.com/firework-for-developers" target="_blank" rel="noreferrer">https://docs.firework.com/firework-for-developers</a></p><h2 id="千易" tabindex="-1">千易 <a class="header-anchor" href="#千易" aria-label="Permalink to &quot;千易&quot;">​</a></h2><p>居然是通过rest api获取订单信息，我以为是webhook呢</p><img width="842" height="168" alt="img_v3_02143_9d2db045-d81e-4aee-afd7-2ef5c098726g" src="https://github.com/user-attachments/assets/0b4c274c-be54-4d14-b411-2be1c2d09a6b">',28)]))}const m=a(i,[["render",s]]);export{c as __pageData,m as default};
